import React from 'react';
import { CTable } from '@cloud-materials/common';

type DataItemType = {
  name: string;
  salary: number;
  address: string;
  email: string;
};

const getData = (pageNumber = 1, pageSize = 10): Promise<{ data: DataItemType[]; total: number }> => {
  const res = {
    data: Array.from({ length: pageSize }).map((_, index) => ({
      key: `${pageNumber}_${index}`,
      name: `William Smith_${pageNumber}_${index}`,
      salary: 23000 + index * 1000,
      address: `${pageNumber}_${index} Park Road, London`,
      email: `william.smith_${pageNumber}_${index}@example.com`,
    })),
    total: 100,
  };
  return new Promise(resolve => {
    setTimeout(() => {
      resolve(res);
    }, 1000);
  });
};

export default () => {
  const config = CTable.defineConfig<DataItemType>({
    columns: [
      {
        title: 'Name',
        dataIndex: 'name',
        // 配置列 title 的 tooltip
        tooltip: '提示信息',
      },
      {
        title: '运行状态',
        // 通过配置内置组件渲染 cell
        component: 'CStatus',
        componentProps: ({ rowData }) => ({
          status: rowData.salary === 25000 ? 'loading' : 'running',
          text: rowData.salary === 25000 ? '重启中' : '运行中',
        }),
      },
      {
        title: 'Salary',
        dataIndex: 'salary',
        // 通过配置 component 为组件来渲染，组件的 props 中具有 table领域模型、row领域模型、rowData 等信息
        component({ rowData }) {
          return (
            <span>
              <span style={{ color: '#FF7D00', fontWeight: 600 }}>$</span>
              {rowData.salary.toLocaleString()}
            </span>
          );
        },
      },
      {
        title: 'Address',
        dataIndex: 'address',
        // 通过 render 来渲染，和 arco 相同
        render(_, rowData) {
          return rowData.address;
        },
      },
      {
        title: 'Email',
        dataIndex: 'email',
      },
    ],
    // table 默认的起始页码是 1
    // 你可以配置 config.startPageNumber 来控制起始页码
    fetcher: async ({ pageSize, currentPage }) => {
      const res = await getData(currentPage, pageSize);
      return {
        data: res.data,
        total: res.total,
      };
    },
  });

  return <CTable config={config} />;
};

