let fetchTimes = 0;

export default () => {
  const config = CTable.defineConfig<DataItemType>({
    mode: 'loadMore',
    // loadMoreContainerHeight 默认高度为 460，可以覆写
    loadMoreContainerHeight: 560,
    // extraConfig: {
    // 如果每次加载时，后端返回的数据条数不定，我们很难动态调整滚动容器的高度来适应数据高度
    // 这时，可以配置加载模式为【点击加载更多】，从而不用依赖容器的 scroll 事件
    //   loadMoreType: 'clickLoadMore',
    // },
    columns: [
      {
        title: 'Name',
        dataIndex: 'name',
      },
      {
        title: 'Salary',
        dataIndex: 'salary',
        formatter: 'int',
      },
      {
        title: 'Address',
        dataIndex: 'address',
      },
      {
        title: 'Email',
        dataIndex: 'email',
      },
    ],
    fetcher: async ({ currentPage, pageSize }) => {
      fetchTimes++;
      if (fetchTimes % 3 === 0) {
        return new Promise((_, reject) => {
          setTimeout(() => {
            reject(new Error('mock error'));
          }, 1000);
        });
      }
      const res = await getData(currentPage, pageSize);
      return {
        // 当没有更多的数据时，需要主动返回 noMore: true
        noMore: fetchTimes > 5,
        data: res.data,
        total: res.total,
      };
    },
  });

  return <CTable config={config} />;
};

