import React from 'react';
import { CTable } from '@cloud-materials/common';
import type { CellComponentRenderProps } from '@cloud-materials/common/es/CTable';
import { useTable, useRow, useCell } from '@cloud-materials/common/es/CTable';

type DataItemType = {
  name: string;
  salary: number;
  address: string;
  email: string;
};

const getData = (pageNumber = 1, pageSize = 10): Promise<{ data: DataItemType[]; total: number }> => {
  const res = {
    data: Array.from({ length: pageSize }).map((_, index) => ({
      key: `${pageNumber}_${index}`,
      name: `William Smith_${pageNumber}_${index}`,
      salary: 23000 + index * 1000,
      address: `${pageNumber}_${index} Park Road, London`,
      email: `william.smith_${pageNumber}_${index}@example.com`,
    })),
    total: 100,
  };
  return new Promise(resolve => {
    setTimeout(() => {
      resolve(res);
    }, 1000);
  });
};

const EmailCellComponent: React.FC<CellComponentRenderProps> = () => {
  // 这里我们在组件内使用 hooks 获取领域模型信息
  const table = useTable();
  const row = useRow();
  const cell = useCell();
  console.log(table, row, cell, cell.column);
  // 把邮箱名加粗显示
  const [name, suffix] = cell.data.split('@');
  return (
    <span>
      <span style={{ fontWeight: 'bold' }}>{name}</span>@<span>{suffix}</span>
    </span>
  );
};

export default () => {
  const config = CTable.defineConfig<DataItemType>({
    pageSize: 10,
    columns: [
      {
        title: '配置 component 实现自定义单元格渲染',
        width: 300,
        // 在 column 的配置中，可以通过 component 来渲染自定义的组件，组件参数中包含完整的领域模型信息和其他数据信息，包括:
        // cellData(单元格数据)，rowData(行数据)，content(经过 format 后的内容)，table(table实例)，row(row实例)，cell(cell实例)，column(column实例)
        component: ({ rowData }) => {
          return (
            <div>
              <span>name: {rowData.name}</span>
              <br />
              <span>address: {rowData.address}</span>
              <br />
              <span>salary: {rowData.salary}</span>
            </div>
          );
        },
      },
      {
        title: '配置 render 实现自定义单元格渲染',
        width: 300,
        dataIndex: 'name',
        // 配置 render 函数，该函数 和 arco table 的 render 参数、行为均一致。
        render: (col, item) => {
          return (
            <div>
              <span>name: {col}</span>
              <br />
              <span>address: {item.address}</span>
              <br />
              <span>salary: {item.salary}</span>
            </div>
          );
        },
      },
      {
        title: 'component 配置为组件',
        width: 300,
        dataIndex: 'email',
        // component 接收一个组件
        component: EmailCellComponent,
      },
    ],
    fetcher: async ({ pageSize, currentPage }) => {
      const res = await getData(currentPage, pageSize);
      return {
        total: res.total,
        data: res.data,
      };
    },
  });

  return <CTable config={config} />;
};

import React from 'react';
