/**
 * 在 table 的插件中，描述 sorter 行为的数据结构为：
 * type Sorter = {
 *   type?: 'default';                     // sorter 插件的名字
 *   directions?: ('ascend'|'descend')[];  // 允许升序或者逆序
 *   sorterFn?: (direction: 'ascend'|'descend', a: any, b: any) => number;  // 排序函数
 *   defaultValue?: 'ascend'|'descend';    // 默认排序方向
 * };
 */
export default () => {
  const config = CTable.defineConfig<DataItemType>({
    // 本地模式下，排序操作时，会调用 sorterFn 进行数据过滤，而不是调用 fetcher 重新请求数据
    // 只有在 local 模式下，配置 sorterFn 才有意义，会直接用 sorterFn 去排序当前数据
    // 远程模式下，sorter 的值会传入 fetcher 重新请求数据
    mode: 'local',
    columns: [
      {
        title: 'Name',
        dataIndex: 'name',
        sorter: {
          type: 'default',
          // 覆写默认的 sorterFn 函数
          // 只有在 local 模式下，配置 sorterFn 才有意义，会直接用 sorterFn 去排序当前数据
          sorterFn(direction: SorterValue, a: string, b: string) {
            // 按照名字长度排序
            if (direction === 'ascend') {
              return a.length - b.length;
            } else {
              return b.length - a.length;
            }
          },
        },
      },
      {
        title: 'Salary',
        dataIndex: 'salary',
        // 直接将 sorter 配置为字符串，相当于 sorter: { type: 'default' } 的简写
        // 内置的 default 类型的排序插件，包含两个内置逻辑
        // 1. 默认逻辑是将对比的两个数据相减
        // 2. 支持升序、降序
        sorter: 'default',
      },
      {
        title: 'Address',
        dataIndex: 'address',
        // sorter 直接配置为函数，相当于 sorter: { sorterFn() {} } 的简写
        sorter: (direction: SorterValue, a: string, b: string) => {
          const numA = parseInt(a);
          const numB = parseInt(b);
          if (direction === 'ascend') {
            return numA - numB;
          } else {
            return numB - numA;
          }
        },
      },
      {
        title: 'Email',
        dataIndex: 'email',
      },
    ],
    fetcher: async ({ pageSize, currentPage }) => {
      const res = await getData(currentPage, pageSize);
      return {
        data: res.data,
        total: res.total,
      };
    },
  });

  return <CTable config={config} />;
};

