/* 在 table 的插件中，描述 rowSelection 的数据结构为：
 * type RowSelection = {
 *   type?: 'radio' | 'checkbox';      // 行选择类型
 *   preserveCrossPageKeys?: boolean;  // 切换分页后是否保留选中项，默认为 false
 *   selectable?: (options: { table: Table<T>; row?: Row<T>; rowData: T }) => boolean;  // 当前行是否禁用选择
 * }
 */
export default () => {
  const tableRef = useRef<TableModel<DataItemType> | null>(null);
  const config = CTable.defineConfig<DataItemType>({
    rowKey: rowData => rowData.name,
    // rowSelection 也可以直接配置为字符串，如 rowSelection: 'checkbox'
    rowSelection: {
      type: 'checkbox',
      // 禁用某些行的选择
      selectable({ rowData }) {
        if (rowData.salary === 26000) {
          return false;
        }
        return true;
      },
    },
    toolbar: {
      bottomLeft: [
        {
          component: 'CToolbarOperationMenu',
          componentProps({ table }) {
            return {
              operations: [
                {
                  name: '打印选中行信息',
                  onClick: () => console.log(table.selectedRowData, table.selectedRowKeys),
                  disabled: table.selectedRowKeys.length === 0,
                },
              ],
            };
          },
        },
      ],
    },
    columns: [
      {
        title: 'Name',
        dataIndex: 'name',
      },
      {
        title: 'Salary',
        dataIndex: 'salary',
      },
      {
        title: 'Address',
        dataIndex: 'address',
      },
      {
        title: 'Email',
        dataIndex: 'email',
      },
    ],
    effects() {
      // 监听行的初始化事件
      CTable.effects.onRowInit<DataItemType>(({ row }) => {
        if (row.data.salary === 25000) {
          // 配置默认选中的行
          // row.setSelect(true);
        }
      });
      // 监听行选择或者取消选择事件
      CTable.effects.onRowSelect<DataItemType>(({ row }) => {
        console.log('onRowSelect', row.isSelected);
      });
    },
    // 通过如下配置可以渲染自定义的 checkbox，比如给禁用态的 checkbox 加 popover
    arcoTableProps: {
      rowSelection: {
        renderCell(originNode, _checked, record: { data: DataItemType }) {
          if (record.data.salary === 26000) {
            return <Popover content="在此可以配置不可选中行的 checkbox 的 popover 内容">{originNode}</Popover>;
          }
          return originNode;
        },
      },
    },
    fetcher: async ({ pageSize, currentPage }) => {
      const res = await getData(currentPage, pageSize);
      return {
        total: res.total,
        data: res.data,
      };
    },
  });

  return (
    <div>
      <span>
        <Button
          style={{ marginBottom: 8, marginRight: 8 }}
          onClick={() => {
            if (tableRef.current) {
              tableRef.current.refresh({ resetSelectedRows: true });
            }
          }}
        >
          强制刷新
        </Button>
        <span>table.refresh 支持传递 resetSelectedRows 参数，配置为 true 时，刷新时会清空已选的行</span>
      </span>
      <CTable config={config} ref={tableRef} />
    </div>
  );
};

