const TableStatusPersistKey = 'TableStatusPersistKey';
// 模拟的状态持久化工具
const cache = {
  map: {} as Record<string, any>,
  get(key: string) {
    return this.map[key];
  },
  set(key: string, value: any) {
    this.map[key] = value;
  },
};

export default () => {
  const [toggle, setToggle] = useState(true);

  const config = CTable.defineConfig<DataItemType>({
    rowKey: rowData => rowData.name,
    pageSize: 10,
    getInitStatus() {
      const status = cache.get(TableStatusPersistKey);
      // 每次消费后，清空状态，避免状态一直存在
      cache.set(TableStatusPersistKey, undefined);
      return status;
    },
    toolbar: {
      right: [
        {
          name: 'instanceName',
          component: 'CSimpleSearch',
          componentProps: { content: { component: 'Input', componentProps: { placeholder: '搜索实例名称' } } },
        },
      ],
    },
    columns: [
      {
        title: '实例名称',
        component({ table, rowData }) {
          return (
            <Button
              type="primary"
              onClick={() =>
                // 保存 table 的状态
                cache.set(TableStatusPersistKey, {
                  ...table.getCurrentStatus(),
                  // 保存 activeRowKey，从而恢复 table 状态时，可以高亮之前点的行
                  activeRowKey: rowData.name,
                })
              }
            >
              保存 Table 状态
            </Button>
          );
        },
      },
      {
        title: 'Salary',
        dataIndex: 'salary',
        render(_, rowData) {
          return (
            <span>
              <span style={{ color: '#FF7D00', fontWeight: 600 }}>$</span>
              {rowData.salary.toLocaleString()}
            </span>
          );
        },
      },
      {
        title: 'Address',
        dataIndex: 'address',
      },
      {
        title: 'Email',
        dataIndex: 'email',
      },
    ],
    fetcher: async ({ pageSize, currentPage }) => {
      const res = await getData(currentPage, pageSize);
      return {
        data: res.data,
        total: res.total,
      };
    },
  });

  return (
    <div>
      <Alert content="重新加载 table 后，可以恢复搜索值、排序状态、pageSize、pageNumber，并且高亮点过的行" />
      <Button onClick={_ => setToggle(pre => !pre)} type="primary">
        {`${toggle ? '卸载' : '加载'} table`}
      </Button>
      {toggle && <CTable config={config} />}
    </div>
  );
};

import React from 'react';
