  salary: number;
  address: string;
  email: string;
};

const getData = (options: FetcherOptions): Promise<{ data: DataItemType[]; total: number }> => {
  const { pageSize, currentPage, filterValues, sorterValues } = options;
  let data = Array.from({ length: pageSize }).map((_, index) => ({
    key: `${currentPage}_${index}`,
    name: `William Smith_${currentPage}_${index}`,
    salary: 23000 + index * 1000,
    address: `${currentPage}_${index} Park Road, London`,
    email: `william.smith_${currentPage}_${index}@example.com`,
  }));

  if (sorterValues?.salary) {
    data.sort((a, b) => {
      if (sorterValues?.salary === 'ascend') {
        return a.salary - b.salary;
      }
      return b.salary - a.salary;
    });
  }

  if (filterValues?.name) {
    data = data.filter(d => filterValues?.name?.includes(d.name));
  }

  if (filterValues?.address) {
    data = data.filter(d => d.name.includes(filterValues?.address));
  }

  const res = {
    data,
    total: 100,
  };
  return new Promise(resolve => {
    setTimeout(() => {
      resolve(res);
    }, 1000);
  });
};

