/**
 * 在 table 的插件中，描述 autoWidth 行为的数据结构为：
 * type Sorter = {
 *   type?: 'default';                                             // autoWidth 插件的名字
 *   getCellWidth?: ({ table, rowData, row, content }) => number;  // 计算单元格的宽度
 *   getHeaderCellWidth?: ({ table, column }) => number;           // 计算 header 单元格的宽度
 *   maxWidth?: number;                                            // 允许的最大宽度，默认为 240px
 *   minWidth?: number;                                            // 允许的最小宽度，默认为 100px
 * };
 */
export default () => {
  const config = CTable.defineConfig<DataItemType>({
    columns: [
      {
        // title 也会参与 cell 的宽度比较，最终取最大的宽度作为该列的宽度
        title: 'NameNameNameNameNameNameNameName',
        dataIndex: 'name',
        autoWidth: {
          type: 'default',
          maxWidth: 400,
        },
      },
      {
        title: 'Salary',
        dataIndex: 'salary',
        // 直接将 autoWidth 配置为字符串，相当于 autoWidth: { type: 'default' } 的简写
        autoWidth: 'default',
        // 按照云计算设计规范，数字应该右对齐标题文字（排除 icon），配置 alignType 即可达到该效果
        alignType: 'right',
        tooltip: '提示信息',
        sorter: 'default',
      },
      {
        title: 'Address',
        dataIndex: 'address',
        autoWidth: 'default',
      },
      {
        title: 'Key',
        dataIndex: 'key',
        // formatter 的返回值，会自动被 autoWidth 接收，用于计算宽度，这也是纯文本列我们更推荐用 formatter 的原因之一
        formatter() {
          return ['aaa79879979797986968765876586', 'bbbb', 'aaaa', 'fafah', 'hhhhh'].join('|');
        },
        autoWidth: {
          type: 'default',
          maxWidth: 800,
        },
      },
      {
        title: 'Email',
        dataIndex: 'email',
        autoWidth: {
          type: 'default',
          maxWidth: 800,
          // 手动计算宽度
          getCellWidth({ rowData }) {
            return CTable.getTextWidth(rowData?.email);
          },
        },
      },
      {
        title: 'Tag',
        dataIndex: 'tag',
        // 可以直接配置宽度，不自适应计算
        width: 400,
        component() {
          const COLORS = ['gold', 'lime', 'green'];
          return (
            <>
              {COLORS.map((color, i) => (
                <Tag key={i} closable color={color} style={{ margin: '0 16px 16px 0 ' }}>
                  {color}
                </Tag>
              ))}
            </>
          );
        },
      },
    ],
    fetcher: async ({ pageSize, currentPage }) => {
      const { data, total } = await getData(currentPage, pageSize);
      // 模拟很宽的内容
      data[0].email = `${data[0].email}-${data[0].email}-${data[0].email}-${data[0].email}`;
      return {
        data: data,
        total: total,
      };
    },
  });

  return (
    <div className="c-demo-table-auto-width">
      <CTable config={config} />
    </div>
  );
};

