          };
        },
        filter: {
          dataSource: [
            { text: '包年包月', value: 'PrePaid' },
            { text: '按量计费', value: 'PostPaid' },
          ],
        },
      },
      {
        title: '操作',
        width: 120,
        fixed: 'right',
        component: 'COperationMenu',
        componentProps: ({ rowData }) => ({
          displayNum: 1,
          operations: [
            {
              name: '远程连接',
              onClick: () => console.log('远程连接'),
            },
            {
              name: '实例状态',
              subOperation: [
                {
                  name: '启动',
                  onClick: () => console.log('启动'),
                  disabled: rowData.status === 'running',
                },
                {
                  name: '停止',
                  onClick: () => console.log('停止'),
                },
              ],
            },
            {
              name: '资源变配',
              subOperation: [
                {
                  name: '更改实例规格',
                  onClick: () => console.log('重启'),
                  disabled: rowData.status === 'running',
                  tooltip: '请先停止实例',
                },
                {
                  name: '按量计费转包年包月',
                  onClick: () => console.log('删除'),
                },
              ],
            },
          ],
        }),
      },
    ],
    fetcher: ({ pageSize, currentPage }) => {
      // table 默认的起始页码是 1
      // 你可以配置 startPageNumber 来控制起始页码
      const data = genData(currentPage, pageSize);
      return mockFetcher({ data, total: 100 }, 1000);
    },
    // 在 table 第一次请求数据之前，执行一个异步动作，beforeInit 的返回值，会保存到 table.globalScope
    // 通常我们可以在这里请求列的筛选项，然后在 filter.dataSource 中消费
    // 也可以请求用于展示时，需要用到的映射数据，如将可用区文案映射为文本
    beforeInit: async () => {
      // 定义一个 mock 获取可用区的接口
      const DescribeZones = () => {
        return Promise.resolve([
          { Description: '可用区A-东湾', ZoneId: 'cn-nanjing-bbit-a' },
          { Description: '可用区B-东湾', ZoneId: 'cn-nanjing-bbit-b' },
          { Description: '可用区C-东湾', ZoneId: 'cn-nanjing-bbit-c' },
        ]);
      };
      const zones = await DescribeZones();

      return new Promise(resolve => {
        setTimeout(() => {
          resolve({
            AllZone: zones,
          });
        }, 1000);
      });
    },
  });

  return <CTable config={config} />;
};
